<?php
// Shared helpers for the SECORVIX blog dashboard and contact form.
// Written for PHP 7.4+ so it runs on standard cPanel hosting.

declare(strict_types=1);

define('DATA_DIR', dirname(__DIR__) . '/_data');
define('UPLOAD_DIR', dirname(__DIR__) . '/uploads');

header('X-Content-Type-Options: nosniff');
header('Referrer-Policy: same-origin');

/* ---------- Config ---------- */

// config.php is generated by the GitHub deploy workflow from repository secrets.
function config(): array
{
    static $config = null;
    if ($config === null) {
        $file = __DIR__ . '/config.php';
        $loaded = is_file($file) ? require $file : [];
        $config = (is_array($loaded) ? $loaded : []) + [
            'admin_email' => '',
            'admin_password_hash' => '',
            'github_token' => '',
            'github_repo' => '',
            'github_workflow' => 'deploy.yml',
            'github_ref' => 'main',
            'build_token' => '',
            'contact_email' => 'contact@secorvix-ai.com',
            'mail_from' => 'contact@secorvix-ai.com',
        ];
    }
    return $config;
}

/* ---------- HTTP ---------- */

function json_response($data, int $status = 200): void
{
    http_response_code($status);
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store');
    echo json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    exit;
}

function fail(string $message, int $status = 400): void
{
    json_response(['error' => $message], $status);
}

function request_json(): array
{
    $data = json_decode((string) file_get_contents('php://input'), true);
    if (!is_array($data)) {
        fail('Invalid request.');
    }
    return $data;
}

function require_method(string $method): void
{
    if ($_SERVER['REQUEST_METHOD'] !== $method) {
        fail('Method not allowed.', 405);
    }
}

function str_field(array $data, string $key, int $max = 500): string
{
    $value = isset($data[$key]) && is_scalar($data[$key]) ? trim((string) $data[$key]) : '';
    return function_exists('mb_substr') ? mb_substr($value, 0, $max) : substr($value, 0, $max);
}

/* ---------- Storage ---------- */

function data_path(string $name): string
{
    if (!is_dir(DATA_DIR)) {
        mkdir(DATA_DIR, 0750, true);
    }
    return DATA_DIR . '/' . $name;
}

function read_json(string $name, $default)
{
    $file = data_path($name);
    if (!is_file($file)) {
        return $default;
    }
    $data = json_decode((string) file_get_contents($file), true);
    return $data === null ? $default : $data;
}

function write_json(string $name, $data): void
{
    $file = data_path($name);
    $tmp = $file . '.' . bin2hex(random_bytes(4)) . '.tmp';
    $json = json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    if ($json === false || file_put_contents($tmp, $json, LOCK_EX) === false || !rename($tmp, $file)) {
        @unlink($tmp);
        fail('Could not save data on the server.', 500);
    }
}

// Serialises read-modify-write cycles across concurrent requests.
function with_lock(callable $fn)
{
    $handle = fopen(data_path('.lock'), 'c');
    flock($handle, LOCK_EX);
    try {
        return $fn();
    } finally {
        flock($handle, LOCK_UN);
        fclose($handle);
    }
}

function now_iso(): string
{
    return gmdate('Y-m-d\TH:i:s\Z');
}

/* ---------- Rate limiting ---------- */

function rate_key(string $bucket): string
{
    return $bucket . ':' . hash('sha256', $_SERVER['REMOTE_ADDR'] ?? 'unknown');
}

function rate_count(string $bucket, int $window): int
{
    $hits = read_json('ratelimit.json', []);
    $since = time() - $window;
    return count(array_filter($hits[rate_key($bucket)] ?? [], function ($t) use ($since) {
        return $t > $since;
    }));
}

function rate_record(string $bucket, int $window): void
{
    with_lock(function () use ($bucket, $window) {
        $hits = read_json('ratelimit.json', []);
        $since = time() - $window;
        foreach ($hits as $key => $times) {
            $hits[$key] = array_values(array_filter($times, function ($t) use ($since) {
                return $t > $since;
            }));
            if (!$hits[$key]) {
                unset($hits[$key]);
            }
        }
        $hits[rate_key($bucket)][] = time();
        write_json('ratelimit.json', $hits);
    });
}

function rate_clear(string $bucket): void
{
    with_lock(function () use ($bucket) {
        $hits = read_json('ratelimit.json', []);
        unset($hits[rate_key($bucket)]);
        write_json('ratelimit.json', $hits);
    });
}

/* ---------- Auth ---------- */

function start_session(): void
{
    if (session_status() === PHP_SESSION_ACTIVE) {
        return;
    }
    $dir = data_path('sessions');
    if (!is_dir($dir)) {
        mkdir($dir, 0750, true);
    }
    session_save_path($dir);
    ini_set('session.gc_maxlifetime', '28800');
    ini_set('session.use_strict_mode', '1');
    session_name('secorvix_admin');
    session_set_cookie_params([
        'lifetime' => 0,
        'path' => '/',
        'secure' => !empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off',
        'httponly' => true,
        'samesite' => 'Strict',
    ]);
    session_start();
}

// Account saved from the dashboard wins; otherwise fall back to the deploy secrets.
function account(): array
{
    $saved = read_json('account.json', null);
    if (is_array($saved) && !empty($saved['email']) && !empty($saved['password_hash'])) {
        return $saved;
    }
    $c = config();
    return ['name' => 'SECORVIX Team', 'email' => $c['admin_email'], 'password_hash' => $c['admin_password_hash']];
}

function current_user(): ?array
{
    start_session();
    return isset($_SESSION['user']) && is_array($_SESSION['user']) ? $_SESSION['user'] : null;
}

// Every dashboard request must carry this header; browsers will not send it cross-site without CORS.
function require_admin(): array
{
    if (($_SERVER['HTTP_X_REQUESTED_WITH'] ?? '') !== 'secorvix-admin') {
        fail('Forbidden.', 403);
    }
    $user = current_user();
    if (!$user) {
        fail('Your session has expired. Please sign in again.', 401);
    }
    return $user;
}

/* ---------- Posts ---------- */

function load_posts(): array
{
    $posts = read_json('posts.json', null);
    if (!is_array($posts)) {
        $posts = seed_posts();
        write_json('posts.json', $posts);
    }
    return $posts;
}

function seed_posts(): array
{
    $seed = json_decode((string) @file_get_contents(__DIR__ . '/seed-posts.json'), true);
    $posts = [];
    foreach (is_array($seed) ? $seed : [] as $p) {
        $posts[] = [
            'id' => bin2hex(random_bytes(8)),
            'slug' => $p['slug'],
            'title' => $p['title'],
            'summary' => $p['summary'],
            'html' => $p['html'],
            'category' => $p['category'],
            'tags' => $p['tags'],
            'author' => $p['author'],
            'cover' => $p['cover'],
            'status' => 'published',
            'publishAt' => $p['date'],
            'createdAt' => $p['date'],
            'updatedAt' => $p['date'],
            'seoTitle' => $p['seoTitle'],
            'seoDescription' => $p['seoDescription'],
        ];
    }
    return $posts;
}

function is_live(array $post): bool
{
    return $post['status'] === 'published' && !empty($post['publishAt']) && strtotime($post['publishAt']) <= time();
}

function post_state(array $post): string
{
    if ($post['status'] !== 'published') {
        return 'draft';
    }
    return is_live($post) ? 'published' : 'scheduled';
}

function read_time(string $html): string
{
    $words = str_word_count(strip_tags($html));
    return max(1, (int) round($words / 200)) . ' min read';
}

// Shape consumed by the Next.js build (src/app/lib/posts.ts).
function public_post(array $p): array
{
    return [
        'slug' => $p['slug'],
        'title' => $p['title'],
        'summary' => $p['summary'],
        'html' => $p['html'],
        'category' => $p['category'],
        'tags' => $p['tags'],
        'author' => $p['author'],
        'cover' => $p['cover'],
        'date' => $p['publishAt'],
        'updated' => $p['updatedAt'],
        'seoTitle' => $p['seoTitle'],
        'seoDescription' => $p['seoDescription'],
        'readTime' => read_time($p['html']),
    ];
}

function slugify(string $text): string
{
    $text = strtolower(trim($text));
    $text = preg_replace('/[^a-z0-9]+/', '-', $text) ?? '';
    return trim(substr($text, 0, 90), '-');
}

/* ---------- HTML sanitising ---------- */

function safe_url(string $url, bool $image): ?string
{
    $url = trim($url);
    if ($url === '') {
        return null;
    }
    if (preg_match('#^https?://#i', $url) || preg_match('#^/(?!/)#', $url)) {
        return $url;
    }
    if (!$image && preg_match('#^(mailto:|tel:|\#)#i', $url)) {
        return $url;
    }
    return null;
}

// Allow-list sanitiser for article HTML produced by the dashboard editor.
function sanitize_html(string $html): string
{
    if (trim($html) === '') {
        return '';
    }

    $allowed = [
        'p' => [], 'br' => [], 'h2' => [], 'h3' => [], 'h4' => [],
        'strong' => [], 'b' => [], 'em' => [], 'i' => [], 'u' => [], 's' => [], 'code' => [],
        'ul' => [], 'ol' => ['start'], 'li' => [], 'blockquote' => [], 'hr' => [],
        'a' => ['href', 'target'], 'img' => ['src', 'alt'], 'span' => ['style'],
        'table' => [], 'colgroup' => [], 'col' => [], 'thead' => [], 'tbody' => [], 'tr' => [],
        'th' => ['colspan', 'rowspan'], 'td' => ['colspan', 'rowspan'],
    ];
    $drop = ['script', 'style', 'iframe', 'object', 'embed', 'form', 'input', 'button', 'textarea',
        'select', 'link', 'meta', 'svg', 'math', 'template', 'frame', 'frameset', 'base'];

    $doc = new DOMDocument();
    $previous = libxml_use_internal_errors(true);
    $doc->loadHTML('<?xml encoding="utf-8"?><div>' . $html . '</div>', LIBXML_HTML_NOIMPLIED | LIBXML_HTML_NODEFDTD);
    libxml_clear_errors();
    libxml_use_internal_errors($previous);

    $root = $doc->documentElement;
    if (!$root) {
        return '';
    }

    $clean = function (DOMNode $node) use (&$clean, $allowed, $drop) {
        foreach (iterator_to_array($node->childNodes) as $child) {
            if ($child instanceof DOMElement) {
                $tag = strtolower($child->tagName);
                if (in_array($tag, $drop, true)) {
                    $node->removeChild($child);
                    continue;
                }
                if (!isset($allowed[$tag])) {
                    // Unknown wrapper: keep its content, drop the tag.
                    $clean($child);
                    while ($child->firstChild) {
                        $node->insertBefore($child->firstChild, $child);
                    }
                    $node->removeChild($child);
                    continue;
                }
                foreach (iterator_to_array($child->attributes) as $attr) {
                    $name = strtolower($attr->name);
                    $value = $attr->value;
                    $keep = in_array($name, $allowed[$tag], true);
                    if ($keep && $name === 'href') {
                        $keep = safe_url($value, false) !== null;
                    } elseif ($keep && $name === 'src') {
                        $keep = safe_url($value, true) !== null;
                    } elseif ($keep && $name === 'style') {
                        $keep = (bool) preg_match('/^\s*color:\s*(#[0-9a-f]{3,8}|rgba?\([\d\s.,%]+\))\s*;?\s*$/i', $value);
                    } elseif ($keep && in_array($name, ['colspan', 'rowspan', 'start'], true)) {
                        $keep = ctype_digit($value);
                    }
                    if (!$keep) {
                        $child->removeAttribute($attr->name);
                    }
                }
                if ($tag === 'img' && $child->getAttribute('src') === '') {
                    $node->removeChild($child);
                    continue;
                }
                if ($tag === 'a') {
                    if ($child->getAttribute('target') !== '') {
                        $child->setAttribute('target', '_blank');
                        $child->setAttribute('rel', 'noopener noreferrer');
                    }
                }
                $clean($child);
            } elseif ($child instanceof DOMComment || $child instanceof DOMProcessingInstruction) {
                $node->removeChild($child);
            }
        }
    };
    $clean($root);

    $out = '';
    foreach ($root->childNodes as $child) {
        $out .= $doc->saveHTML($child);
    }
    return $out;
}

/* ---------- Site rebuild ---------- */

function auto_publish_enabled(): bool
{
    $c = config();
    return $c['github_token'] !== '' && $c['github_repo'] !== '';
}

// Starts the GitHub Actions deploy so the static blog pages are regenerated.
function trigger_rebuild(): array
{
    if (!auto_publish_enabled()) {
        return ['triggered' => false, 'message' => 'Automatic publishing is not configured yet.'];
    }
    $c = config();
    $url = 'https://api.github.com/repos/' . $c['github_repo'] . '/actions/workflows/' . $c['github_workflow'] . '/dispatches';
    $body = json_encode(['ref' => $c['github_ref']]);
    $headers = [
        'Accept: application/vnd.github+json',
        'Authorization: Bearer ' . $c['github_token'],
        'Content-Type: application/json',
        'User-Agent: secorvix-blog-admin',
        'X-GitHub-Api-Version: 2022-11-28',
    ];

    $status = 0;
    if (function_exists('curl_init')) {
        $ch = curl_init($url);
        curl_setopt_array($ch, [
            CURLOPT_POST => true,
            CURLOPT_POSTFIELDS => $body,
            CURLOPT_HTTPHEADER => $headers,
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT => 15,
        ]);
        curl_exec($ch);
        $status = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);
    } else {
        $context = stream_context_create(['http' => [
            'method' => 'POST',
            'header' => implode("\r\n", $headers),
            'content' => $body,
            'timeout' => 15,
            'ignore_errors' => true,
        ]]);
        @file_get_contents($url, false, $context);
        if (isset($http_response_header[0]) && preg_match('/\s(\d{3})\s/', $http_response_header[0], $m)) {
            $status = (int) $m[1];
        }
    }

    if ($status === 204) {
        with_lock(function () {
            $state = read_json('state.json', []);
            $state['lastTrigger'] = now_iso();
            write_json('state.json', $state);
        });
        return ['triggered' => true, 'message' => 'The website is updating. Changes will be live in about 3 minutes.'];
    }
    return ['triggered' => false, 'message' => 'Saved, but the website update could not be started (GitHub returned ' . $status . ').'];
}
